#include <cstdio>
#include "hardware_native/direct_language_plan_causal_lowering.cuh"
using namespace substrate::direct_network;using namespace substrate::direct_causal_program;
static DirectLanguageMotorPlan plan(std::uint32_t word_bias=0){DirectLanguageMotorPlan p{};p.admitted=1;p.step_count=5;p.supporting_transitions=4;p.distinct_channels=2;p.revision_identity=0xabcddcbaULL;for(std::uint32_t i=0;i<5;++i){p.steps[i].node=300+i;p.steps[i].channel=20+(i&1);p.steps[i].word=0x41410000u+word_bias+i;p.steps[i].due_offset=i+1;}return p;}
int main(){auto a=plan(0),b=plan(0x10100);auto pa=lower_language_plan_to_causal_program(a,0x55,(7ull<<32)|3ull,140);auto pb=lower_language_plan_to_causal_program(b,0x55,(7ull<<32)|3ull,140);auto c=a;c.steps[2].channel+=1;auto pc=lower_language_plan_to_causal_program(c,0x55,(7ull<<32)|3ull,140);auto d=a;d.revision_identity+=1;auto pd=lower_language_plan_to_causal_program(d,0x55,(7ull<<32)|3ull,140);auto bad=lower_language_plan_to_causal_program(a,0,(7ull<<32)|3ull,140);bool word_free=pa.identity==pb.identity;for(unsigned i=0;i<5;++i)word_free&=pa.steps[i].node==pb.steps[i].node&&pa.steps[i].channel==pb.steps[i].channel&&pa.steps[i].due_offset==pb.steps[i].due_offset;bool green=pa.identity&&word_free&&pc.identity!=pa.identity&&pd.identity!=pa.identity&&bad.identity==0&&pa.step_count==5&&pa.depth==4;std::printf("FOUNDRY_DIRECT_LANGUAGE_PLAN_CAUSAL_LOWERING_%s steps=%u depth=%u frozen_surface=0 word_mutation_invariant=%u carrier_mutation_distinct=%u revision_mutation_distinct=%u\n",green?"GREEN":"RED",pa.step_count,pa.depth,word_free?1u:0u,pc.identity!=pa.identity,pd.identity!=pa.identity);return green?0:1;}
